# owner: platform
"""Contact sheet for substitute teachers."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(people: List[Student]) -> None:
    if not people:
        raise ProjectError("no students for contact sheet")
    for item in people:
        if not (item.email or "").strip():
            name = item.display_name
            raise ProjectError(f"no email for {name}")


def _sort_key(item: Student) -> Tuple[str, str]:
    last = item.last_name.casefold()
    return (last, item.first_name.casefold())


def _cells(item: Student) -> Tuple[str, str, str]:
    mail = item.email.strip()
    return (item.display_name, item.section, mail)


def _line(cells: Tuple[str, ...], widths: List[int]) -> str:
    pairs = zip(cells, widths)
    padded = [text.ljust(wide) for text, wide in pairs]
    return "  ".join(padded).rstrip()


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    people = list(students)
    _check(people)
    people.sort(key=_sort_key)
    table = [_cells(item) for item in people]
    columns = zip(*table)
    widths = [max(map(len, group)) for group in columns]
    return [_line(cells, widths) for cells in table]
